    "id": "mme_skeleton_dragon_e",
    "name": "Древний Скелет Дракон",
    "description": "Скелеты драконов — каркасы из костей, сохранившие ужасающий силуэт и физиологический арсенал своих живых версий. Хотя по природе они схожи с простыми человеческими скелетами, они полностью затмевают их своим масштабом и наносят некротический урон вместо того чтобы извергать элементальное дыхание.\n\nЭти неживые чудища часто являются мрачными последствиями использования запретной некромантии. Когда амбициозная попытка Культа Драконов создать очередного драколича проваливается в следствие слабой филактерии или стойкого драконьего духа, затраченная магия должна создать нечто иное. То что остаётся — бездушный монстр, прикованный к воле культистов, лишённый гениального интеллекта драколича, но выступающий в качестве неудержимого осадного орудия.\n\nДревний скелет дракон — это огромная разрушительная сила с невероятно прочными костями и смертоносным размахом крыльев в 4,5 метра.  Эти колоссальные чудовища, пропитанные темной магией, могут трижды в день обрушивать на врагов магический ужас, полностью подрывая их боевой дух.\n\nВ исторических источниках упоминаются подобные костяные титаны, которых поднимали отчаявшиеся заклинатели. Например, леди Фаркаттл оживила гигантский скелет глубинного дракона, чтобы подчинить себе племена хобгоблинов в горах Гигантского пика.\n\nРыцари смерти и личи держат этих неживых титанов в качестве главных боевых единиц своих армий и используют их только для захвата крепостей или сокрушения самых могущественных противников.",
    "type": "Гигантский Нежить, законно-злой",
