    "id": "mme_shaytan_s",
    "name": "Шайтан Солар",
    "description": "В то время как большинство падших ангелов сбились с пути из-за влияния Асмодея, некоторые поддались искушениям Граз'зта, Тёмного Князя Удовольствий, или Малкантет, Королевы Суккубов. Этих ангелов называют шайтанами или шайатинами. Некогда прекрасные и величественные, они превратились в тёмных и злобных существ, утративших свою былую сущность.\n\nЭти ангелы утратили часть своих способностей, в том числе высокую скорость полёта, устойчивость к магии и способность излучать энергию. Из-за этих изменений большинство из них сошло с ума. Теперь они переродились в демонов и черпают силу в Царстве теней и Бездне. Их тела всегда окутаны клубящимися тенями, а глаза горят адским пламенем.\n\nКогда-то они были посланниками и исполнителями воли своих богов, а теперь служат Князьям демонов в качестве убийц и военачальников, часто возглавляя теневых демонов в их миссиях.  Извращённые и мстительные, они строят козни и выжидают удобного момента, чтобы посеять хаос и нанести максимальный урон своим бывшим богам, которые их покинули, часто нанося удары по тем, кто им поклоняется.\n\nЭтот крайне редкий падший солар, являющийся последней защитой правящего князя демонов, выступает в роли верховного телохранителя и главнокомандующего.  Поскольку по своей ошеломляющей мощи они не уступают своим повелителям, за этими мрачными военачальниками ведется постоянное наблюдение, чтобы не допустить внезапного переворота в Бездне.\n\nВ мире смертных шайтаны солары обычно занимаются тем, что раскапывают запретные связующие ритуалы в бескрайних степях Нар Фелла или охраняют утраченные реликвии под разрушенной столицей Шунаха.  Они парят над землей на обсидиановых крыльях, вооруженные невероятно огромным луком, который несет мгновенную смерть любому существу, не обладающему необычайной живучестью.\n\nСтолкнувшись с вражеским авангардом, падший солар мгновенно испускает парализующий взгляд, полный ужаса, чтобы остановить приближающихся воинов.  Затем он изящно телепортируется по арене, обрушивая на врагов стрелы, разъедающие плоть, и приказывает автономному летающему клинку методично расправляться с противниками, оказавшимися в окружении.",
