    "description": "Оживлённые статуи представляют собой большие, искусно вырезанные фигуры высотой от 2,5 до 3,5 метров, которые обычно можно встретить в храмах, садах, склепах и дворцовых залах.  Их неподвижные формы часто сливаются с окружающей обстановкой, пока внезапно не оживают.\n\nОживлённые статуи, которых часто путают с настоящими големами, представляют собой менее сложных конструктовв, созданных с помощью более простых заклинаний.  Они менее мощные, но гораздо более доступные по цене, поэтому их часто используют в качестве охранников или для отпугивания воров и нарушителей границ.  Богатые дворяне, купцы и преступные синдикаты иногда покупают таких существ для защиты, хотя их иногда обманывают нечестные волшебники или ремесленники, продающие им оживлённые статуи вместо настоящих големов.\n\nКак и оживлённые доспехи, многие оживлённые статуи наделены магической речью. С помощью запрограммированных голосов они могут предупреждать об опасности, требовать пароль, загадывать загадки или объявлять себя големами, чтобы отпугнуть незваных гостей. Некоторые даже имитируют разговор, создавая жуткую иллюзию разумности.\n\nОживлённые статуи обычно устанавливают в роскошных купеческих поместьях Аткатлы, чтобы отпугивать амбициозных грабителей, желающих проникнуть в амнийские хранилища.  Они также украшают ухоженные королевские сады Сюзейла, обеспечивая кормирской знати элегантную и незаметную защиту.  Кроме того, параноидальные патриархи часто нанимают этих неутомимых стражей для охраны обширных семейных склепов под симбийским городом Селгонт, чтобы их фамильные сокровища оставались нетронутыми.\n\nОживлённые каменные статуи высекаются из мрамора, гранита или известняка и изображают королей, воинов, ангелов или божественных защитников. Их обычно устанавливают в склепах, храмовых коридорах, дворцовых переходах или мавзолеях, и они органично вписываются в ансамбль подлинных мемориальных скульптур. Благодаря потертому виду и тщательно проработанным деталям они остаются незамеченными и годами стоят неподвижно, пока кто-нибудь не запустит их тайное оживление.",
