    "description": "Высшая банши — более могущественная и злобная разновидность обычной банши. Её призрачная форма окутана клубами бледного тумана и теней. На первый взгляд она ничем не отличается от обычной банши, что позволяет ей усыплять бдительность искателей приключений. Только когда она проявляет всю свою силу, её аура темнеет и выдаёт гнетущее присутствие, выдающее в ней нечто гораздо более ужасное.\n\nПо сравнению со своими меньшими сородичами, высшая банши гораздо опаснее из-за своей способности издавать смертоносный вой несколько раз за одну схватку. Она легко проходит сквозь твёрдые предметы и подвергает своих жертв психическим мучениям, подбираясь всё ближе, чтобы убить. Те, кто сталкивается с ней, быстро понимают, что её выносливость и невероятная злоба делают её гораздо более опасным духом, чем любая обычная банши.",
