    "description": "Древняя банши — это искажённый образ некогда могущественного заклинателя, обладавшего значительным влиянием, будь то королева, королевский советник или мастер-волшебник. Их падение было вызвано личными недостатками, такими как зависть, высокомерие или безжалостные амбиции. После смерти они сохраняют остатки былого интеллекта, но их поглощают злоба и скорбь.\n\nЭти духи затаили глубокую обиду и охотятся на потомков тех, кто их предал или затмил. Сохранившиеся у них тайные знания усиливают их способности банши, позволяя им использовать мощные заклинания вместе со своими воплями. Любой, кто потревожит их покой или перейдет им дорогу, столкнется с безжалостным и мстительным врагом.",
