    "name": "Молодой Бехир",
    "description": "Эти вытянутые рептилии, только что вылупившиеся из яиц, спрятанных в скалистых вершинах Закатных гор, быстро превращаются в безжалостных хищников.  Их гладкие тела, покрытые лазурной чешуей, позволяют им с поразительной ловкостью преодолевать коварные ущелья и расщелины.  Подчиняясь врожденному инстинкту защищать свою территорию, эти юные хищники смело бросаются на любого, кто осмелится вторгнуться в их недавно обустроенные логова.\n\nПри нападении на цель они щелкают челюстями, нанося тяжелые раны и одновременно выпуская разряд электрического тока.  Если противник оказывается стойким, быстрый ползун обвивает его своим извивающимся телом, с силой ломая кости и обездвиживая жертву.  Против группы противников они могут выпустить из пасти концентрированный заряд электрического тока, который испепелит нескольких врагов, стоящих на одной линии.",
