    "name": "Бехолдер, Абсолютный Тиран",
    "description": "Абсолютный тиран, которого также называют матерью улья, — это колоссальный бехолдер, который может вырастать до 4,5 метров в диаметре, что делает его значительно крупнее своих меньших сородичей. Его шкура толще и покрыта тяжелыми пластинами, глазные стебельки длиннее и многочисленнее, а центральный глаз излучает сокрушительную силу, которой инстинктивно боятся меньшие бехолдеры.\n\nАбсолютный тиран правит, подавляя любое инакомыслие и принуждая к повиновению с помощью магической силы и подавляющей харизмы.  В отличие от обычных бехолдеров, которые изолируются или вступают в жестокую борьбу, мать улья поддерживает структурированные сообщества, в которых все остальные бехолдеры подчиняются ей в рамках жесткой иерархии.  Древние сферы могут выступать в роли советников, но даже они склоняются перед ее превосходством, потому что ни один бехолдер не осмеливается бросить вызов власти абсолютного тирана.\n\nЕго лучи имеют ту же природу, что и лучи обычного бехолдера, но каждый из них обладает гораздо большей силой, точностью и разрушительной мощью.  Помимо врожденных лучей, абсолютный тиран владеет невероятно мощной тайной магией, которая позволяет ему соперничать в могуществе с архимагами и по своему желанию менять ход битвы.\n\nВ Забытых Королевствах ходят слухи, что в скрытых анклавах бехолдеров в глубинах Подземья правят матери улья. Существа, ощутившие на себе их влияние, шепчут их имена с опаской.  Некоторые ученые считают, что в крайне нестабильных регионах, таких как Глубинные пустоши, или в отдаленных пещерах под Паровым озером, а также в далеких владениях Астрального плана, скрывается абсолютный тиран, который манипулирует низшими бехолдерами, чтобы расширить свою невидимую империю.",
