    "id": "gorgimera",
    "name": "Горгимера",
    "description": "Горгимера — это неестественное слияние химеры и горгоны, которое заменяет её козьи черты металлической бычьей головой и железночешуйчатыми задними частями. Её три отдельные головы рычат и сталкиваются на сильно бронированном туловище, блестящем как живая сталь на солнце. Далеко более волатильная, чем стандартные химеры, эта территориальная чудовищность реагирует на любое вторжение в свой регион немедленной и сокрушительной враждебностью. Она безумно атакует всё, что бродит рядом с её логовом, расценивая любое движение либо как еду для пожирания, либо как угрозу для уничтожения. Во время боя существо одновременно выдыхает смертоносный драконий элементальный взрыв вместе с ужасающим окаменяющим газом горгоны. Пока эти ядовитые пары заставляют конечности противника быстро затвердевать в твёрдый камень, зверь безжалостно топчет обездвиженную жертву под своими тяжёлыми копытами. Из-за своего искусственного происхождения и биологической неспособности размножаться, эти опасные гибриды остаются исключительно редкими по всему Фейруну. Однако изолированные сообщения постоянно предупреждают об этих мерзостях, бродящих по рваным просторам Дикой Окраины, охотившихся у магических лесов Шадодала и ползающих по замерзшим склонам Ледяной Вершины.",
