    "description": "Теневые клоуки, также называемые теневыми плащами, — зловещие существа, исковерканные длительным воздействием удушливой мрачности Тени. Их тела напоминают огромные, рваные плащи из живой тьмы, с бледными глазами, слабо светящимися из меняющихся складок. Когда они расправляют свои огромные крылья, они выглядят как дрейфующие хищные тени, скользящие бесшумно через Подземье. Теневые клоуки — жестокие и расчётливые, они охотятся ради чистого удовольствия от мучений жертв перед убийством. Они преследуют пещерные сети с терпеливой жестокостью, используя тьму и путаницу, чтобы изолировать добычу. Хотя они дики в своих аппетитах, они демонстрируют тревожный интеллект, часто играя с целями задолго до удара. Теневые клоуки используют свои силы, продиктованные тенью, чтобы сбивать с толку и дезориентировать врагов, маскируя свои движения меняющимися иллюзиями и удушливой тьмой. Они атакуют сверху или сзади, цепляясь за жертв своими телами-плащами и высасывая их жизненную силу вампирическим укусом. Ослабив цель, они скользят обратно в тени, чтобы избежать возмездия, прежде чем ударить снова.",
