    "id": "greater-cockatrice",
    "name": "Высший кокатрис",
    "description": "Большой кокатрис — чудовищный и кошмарный этап эволюции обычного кокатриса, достигающий размеров с лошадь и обладающий гораздо более рептильными чертами. Его тело покрыто кожаными чешуйками, прерываемыми рваными лоскутами перьев, а длинный змеевидный хвост оканчивается ядовитым жалом, а крючковатый клюв капает токсичным слизью. Это существо сохраняет окаменяющий укус своих меньших сородичей, но также выпускает жуткий, дрожащий в костях крик, заставляющий лопаться сосуды и мгновенно убивающий слабых. Те, кто достаточно силен, чтобы выдержать звук, часто бегут, прежде чем он ударит снова. К счастью, встречи с большими кокатрисами редки, так как они избегают населённых регионов и пребывают в заброшенных руинах, безжизненных пустошах и других заброшенных местах. Могущественные существа, такие как дао и аристократы ламиа, иногда держат их в качестве стражей, полагаясь на их смертоносное присутствие, чтобы отвратить 침입者. Алхимики, изобретатели и заклинатели жаждут почти каждой части большого кокатриса для мощных смесей, зачарований и редких магических формул, предлагая большие суммы за успешную охоту. Мало кто из искателей приключений возвращается от таких заданий, и те, кто возвращается, часто обнаруживают, что награда едва компенсирует пережитый ужас. Больших кокатрисов часто замечают бродящими по засушливым просторам Пустыни Калим. Они также устраивают скрытые гнёзда по обожжённым дюнам Анауроха, где аристократы ламиа используют их для патрулирования периметров зарытых анклавов. Кроме того, неосторожные исследователи, пробирающиеся через проклятые овраги Холмов Змей, регулярно натыкаются на эти перерослые ужасы, гнездящиеся среди пугающих полей окаменевшей добычи.",
