    "description": "Большой куатль — это более крупная и возвышенная форма обычного куатля, его чешуя сияет более глубокими ирисцентными оттенками, а сияющие крылья оставляют за собой следы небесного света. По мере приближения к концу жизни куатль становится больше и светлее, а его врождённая магия становится намного сильнее. Эти почтенные змеи редки и чтимы, часто рассматриваемые как живые глашатай воли божества. Большие куатли спокойны, мудры и глубоко целеустремленны, действуя только в исполнении священного поручения, вверенного им могущественным божественным существом. Их роли могут включать охрану целого народа, защиту святой реликвии или бодрствование до наступления давно предсказанного события. Когда их божественное задание наконец выполняется, большой куатль создаёт единственное чудесное яйцо и затем тихо уходит из мира, оставляя своё наследие новой жизни внутри. В далеких землях Мазтики эти возвышенные сущности широко поклоняются как прямые посланники благожелательного бога перьевого дракона КOTAL. Кроме того, в глубине густых джунглей Чульт несколько таких древних стражей тайно защищают заросшие святилища, посвящённые расколотому божеству Убтао.",
